// Pass artwork, base64. Apple silently rejects a .pkpass missing icon.png.
//
// logo.png stacks the academix wordmark over MIX & GREET: Wallet draws logoText
// to the RIGHT of the logo with no way to place it below, so line two lives in
// the image. Capped at Apple's 160pt width, which is what stopped the top
// notch from clipping the wordmark.
//
// strip.png is the layered plate — gradient, 45rpm rings re-inked red, a left
// scrim and grain. Deliberately carries NO text: Wallet prints primaryFields
// over this image, so anything baked in would collide with the event name.
// strip and background are mutually exclusive; strip wins for a ticket.
export const PASS_IMAGES: Record<string, string> = {
  "icon.png": "",
  "icon@2x.png": "",
  "icon@3x.png": "",
  "logo.png": "",
  "logo@2x.png": "",
  "logo@3x.png": "",
  "strip.png": "",
  "strip@2x.png": "",
  "strip@3x.png": ""
};
